function normalizeBrand(value) {
  const lower = String(value || '').toLowerCase();
  let out = '';
  for (const ch of lower) {
    out += Object.prototype.hasOwnProperty.call(CYRILLIC_TO_LATIN, ch) ? CYRILLIC_TO_LATIN[ch] : ch;
  }
