  out = out.split('c').join('k').split('').join('ch');
  out = out.split('g').join('h').split('y').join('i').split('j').join('i');
  let collapsed = '';
  for (const ch of out) {
    if (collapsed.charAt(collapsed.length - 1) !== ch) collapsed += ch;
  }
  return collapsed;
}

