  try {
    const v = (typeof $vars !== 'undefined' && $vars[name]) || null;
    if (v) return v;
  } catch (e) { /* Variables unavailable - fall through to env */ }
  try {
    const v = (typeof $env !== 'undefined' && $env[name]) || null;
    if (v) return v;
  } catch (e) { /* env access denied - n8n Cloud */ }
