            '👤 Акаунт «Сільпо»: ' + (authorized ? 'підключено' : 'не підключено') + '\n' +
            '🚫 Марок у винятках: ' + blockedCount + '\n' +
            '📦 Різниця в фасуванні: ' + toleranceLabel(tolerance),
