        lines.length + ' ' + plural(lines.length, 'товар', 'товари', 'товарів') +
        ' · <b>' + money(total) + '</b>\n' +
        RULE + '\n';
    const names = clipAll(shown.map((item) => item.name), 38);
    text += shown
        .map((item, index) => {
