    if (extras.discount && extras.discount > 0)
        notes.push('🎁 Знижок уже враховано · <b>' + money(extras.discount) + '</b>');
    if (extras.bonusAvailable && extras.bonusAvailable > 0)
        notes.push('💳 Балабонуси · ' + money(extras.bonusAvailable));
    if (notes.length)
        text += '\n' + RULE + '\n' + notes.join('\n');
