    return {
        text: '🛒 <b>Оптимізатор кошика «Сільпо»</b>\n\n' +
            'Знайду дешевші аналоги, акції та купони для вашого кошика — без змін у суті покупки.\n\n' +
            '🔒 Нічого не змінюю без вашого підтвердження.',
